import SwiftUI

struct HttpApiClient: View {
    enum Method: String {
        case GET
        case POST
    }

    enum FailureReason: String {
        case timeout
        case network
        case http_4xx
        case http_5xx
    }

    struct RequestStartedPayload {
        let method: Method
        let path: String
    }

    struct RequestSucceededPayload {
        let status: Int
        let duration_ms: Int
    }

    struct RequestFailedPayload {
        let reason: FailureReason
        let status: Int
    }

    var base_url: String
    var timeout_ms: Int = 10000
    var max_retries: Int = 3
    var auth_token: String? = nil

    var onRequestStarted: ((RequestStartedPayload) -> Void)? = nil
    var onRequestSucceeded: ((RequestSucceededPayload) -> Void)? = nil
    var onRequestFailed: ((RequestFailedPayload) -> Void)? = nil

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("HTTP-API-Client")
                .font(.headline)
            Text("base_url: \(base_url)")
            Text("timeout_ms: \(timeout_ms)")
            Text("max_retries: \(max_retries)")
            Text("auth_token: \(auth_token ?? "—")")
        }
        .padding()
    }
}
